        class _RNGShim:
    def __init__(self, seed: int):
        import random as _random
        self._seed = int(seed)
        self._r = _random.Random(self._seed)

    def random(self): return self._r.random()
    def uniform(self, a, b): return self._r.uniform(a, b)
    def randint(self, a, b): return self._r.randint(a, b)
    def randrange(self, *args): return self._r.randrange(*args)
    def choice(self, seq): return self._r.choice(seq)
    def choices(self, population, weights=None, cum_weights=None, k: int = 1):
        return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
    def sample(self, population, k: int): return self._r.sample(population, k)
    def shuffle(self, x):
        self._r.shuffle(x)
        return x
    def getrandbits(self, k: int): return self._r.getrandbits(k)

        import math

def generator(rng):
    # We generate R, L=2a, d such that: 0 < a < R, h = sqrt(R^2 - a^2) > 0, and h < d < R
    # This guarantees two equal-length chords at distance h from the center can intersect at distance d.
    for _ in range(200):
        R = rng.randint(25, 80)
        # choose a moderately sized half-chord to avoid degenerate h
        a = rng.randint(4, R-4)
        if a <= 0 or a >= R:
            continue
        h2 = R*R - a*a
        if h2 <= 0:
            continue
        h = math.sqrt(h2)
        lb = int(math.floor(h)) + 1
        ub = R - 1
        if lb >= ub:
            continue
        d = rng.randint(lb, ub)
        L = 2*a
        # Return assignment
        return {
            'radius': R,
            'chord_len': L,
            'intersection_dist': d
        }
    # Fallback in case of rare failure
    # Choose a safe deterministic set
    R = 42
    a = 10
    L = 2*a
    h2 = R*R - a*a
    d = int(math.floor(math.sqrt(h2))) + 1
    return {
        'radius': R,
        'chord_len': L,
        'intersection_dist': d
    }

