def verifier(assign):
    # Validate presence and types
    try:
        R = int(assign['radius'])
        L = int(assign['chord_len'])
        d = int(assign['intersection_dist'])
    except Exception:
        # Missing or invalid types
        return (False, None)  # invalid
    # Domain checks
    if R <= 0 or L <= 0 or d <= 0:
        # Non-positive parameters
        return (False, None)
    if L % 2 != 0:
        # Chord length must be even: L = 2a
        return (False, None)
    a = L // 2
    if not (0 < a < R):
        # Half-chord must be strictly less than radius
        return (False, None)
    h2 = R*R - a*a
    if h2 <= 0:
        # Degenerate chord (no real distance from center)
        return (False, None)
    h = math.sqrt(h2)
    # Intersection must be inside the circle and geometrically feasible (d > h ensures an angle exists)
    if not (h < d < R):
        return (False, None)
    # Compute S = x^2 + y^2 + 4xy for an unequal region.
    # For equal chords, the two unequal regions have boundary segments of lengths (a - t) and (a + t),
    # where t = sqrt(d^2 - h^2). Their product xy = (a - t)(a + t) = a^2 - t^2 = R^2 - d^2 and x + y = 2a = L.
    # Hence S = (x+y)^2 + 2xy = L^2 + 2(R^2 - d^2).
    S = L*L + 2*(R*R - d*d)
